mapper.select:
SELECT o.o_no, o.o_email, o.o_merchant_uid, o.o_created_at, o.o_amount, o.o_address, o.o_status, pay.pay_status, p.p_title, p.p_image FROM `order` o LEFT JOIN payment pay ON o.o_merchant_uid = pay.pay_merchant_uid LEFT JOIN order_item oi ON o.o_no = oi.oi_order_no LEFT JOIN product p ON oi.oi_product_id = p.p_productid WHERE 1=1 AND pay.pay_status IN ('READY','PAID')
AND o.o_email LIKE CONCAT('%', #{kw}, '%')
AND o.o_no = #{kw}
AND p.p_title LIKE CONCAT('%', #{kw}, '%')
AND oi.oi_product_id LIKE CONCAT('%', #{kw}, '%')
AND DATE(o.o_created_at) >= #{from}
AND DATE(o.o_created_at) <= #{to}
AND pay.pay_status = #{status}
ORDER BY o.o_created_at DESC
